from threading import Lock


def rate_limit(leak_rate, capacity, clock):
    if leak_rate < 0:
        raise ValueError("leak_rate must be non-negative")
    if capacity <= 0:
        raise ValueError("capacity must be positive")

    def decorator(func):
        water = 0.0
        last_leak = None
        lock = Lock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal water, last_leak

            with lock:
                now = clock()
                if last_leak is None:
                    last_leak = now
                else:
                    elapsed = max(0.0, now - last_leak)
                    water = max(0.0, water - elapsed * leak_rate)
                    last_leak = now

                if water + 1 > capacity:
                    return False
                water += 1

            return func(*args, **kwargs)

        return wrapper

    return decorator

